WITH scored AS (SELECT *, LAG(monthly_fee) OVER w_recent AS prev_monthly_fee, LEAD(monthly_fee) OVER w_recent AS next_monthly_fee, ROW_NUMBER() OVER w_recent AS seq_no FROM subscriptions WHERE customer_id IS NULL WINDOW w_recent AS (PARTITION BY customer_id ORDER BY end_date, id)) SELECT s.id, s.customer_id, s.plan, s.start_date, s.end_date, s.monthly_fee, s.status, s.prev_monthly_fee, s.next_monthly_fee, (SELECT SUM(s2.monthly_fee) FROM subscriptions s2 WHERE s2.customer_id = s.customer_id) AS sum_subscription_monthly_fee FROM scored s ORDER BY start_date
